            if 0 <= x < w and 0 <= y < h and (x, y) not in obstacles:
                resources.append((x, y))

    if not resources:
        return [0, 0]

    def dist8(a, b):
        dx = a[0] - b[0]
        dy = a[1] - b[1]
        if dx < 0:
            dx = -dx
        if dy < 0:
            dy = -dy
        return dx if dx > dy else dy

    my_win = []
    for r in resources:
        dm = dist8((sx, sy), r)
        do = dist8((ox, oy), r)
        if dm < do:
            my_win.append((dm - do, r))
    if my_win:
